/** Hidden sprite with every icon; print once, right after <body>. */
function icon_sprite()
{
    $out = '<svg xmlns="http://www.w3.org/2000/svg" width="0" height="0" style="position:absolute" aria-hidden="true" focusable="false"><defs>';
    foreach (icon_defs() as $name => $inner) {
        $out .= '<symbol id="ic-' . $name . '" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round">' . $inner . '</symbol>';
    }
    return $out . '</defs></svg>';
}

function icon($name, $class = '')
{
    return '<svg class="ico' . ($class !== '' ? ' ' . e($class) : '') . '" aria-hidden="true" focusable="false"><use href="#ic-' . e($name) . '"></use></svg>';
}

